func TestCostTxnIncludesNestedTransactions(t *testing.T) {
	put := func(key, value string) *pb.RequestOp {
		return &pb.RequestOp{Request: &pb.RequestOp_RequestPut{RequestPut: &pb.PutRequest{
			Key: []byte(key), Value: []byte(value),
		}}}
	}
	txn := func(success, failure []*pb.RequestOp) *pb.RequestOp {
		return &pb.RequestOp{Request: &pb.RequestOp_RequestTxn{RequestTxn: &pb.TxnRequest{
			Success: success, Failure: failure,
		}}}
	}

	tests := []struct {
		name string
		rt   *pb.TxnRequest
		want int
	}{
		{
			name: "nested success branch",
			rt: &pb.TxnRequest{Success: []*pb.RequestOp{
				txn([]*pb.RequestOp{put("success", "value")}, nil),
			}},
			want: costPut(&pb.PutRequest{Key: []byte("success"), Value: []byte("value")}),
		},
		{
			name: "nested failure branch",
			rt: &pb.TxnRequest{Failure: []*pb.RequestOp{
				txn(nil, []*pb.RequestOp{put("failure", "value")}),
			}},
			want: costPut(&pb.PutRequest{Key: []byte("failure"), Value: []byte("value")}),
		},
		{
			name: "nested branch uses larger of its branches",
			rt: &pb.TxnRequest{Success: []*pb.RequestOp{
				txn([]*pb.RequestOp{put("small", "v")}, []*pb.RequestOp{put("larger-key", "larger-value")}),
			}},
			want: costPut(&pb.PutRequest{Key: []byte("larger-key"), Value: []byte("larger-value")}),
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := costTxn(tt.rt); got != tt.want {
				t.Fatalf("costTxn() = %d, want %d", got, tt.want)
			}
		})
	}
}

